-- the original lists and rename compliance_version_errors_core back (see the footer comment).

-- 1. Widen the kind / surface CHECKs ------------------------------------------------------
DO $$
DECLARE c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'public.compliance_rules'::regclass AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%recording_consent%'
  LOOP
    EXECUTE format('ALTER TABLE public.compliance_rules DROP CONSTRAINT %I', c.conname);
  END LOOP;
  ALTER TABLE public.compliance_rules ADD CONSTRAINT compliance_rules_kind_check
    CHECK (kind IN ('recording_consent', 'ai_disclosure', 'quiet_hours', 'consent_required', 'license_display',
                    'rescission', 'required_notice', 'price_cap',
                    'fm_nte_cap', 'fm_proposal_before_parts', 'fm_invoice_deadline', 'fm_ineligibility_window',
                    'fm_prohibited_line_item', 'fm_single_invoice', 'fm_required_attachment'));

  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'public.compliance_evaluations'::regclass AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%contract%' AND pg_get_constraintdef(oid) ILIKE '%surface%'
  LOOP
    EXECUTE format('ALTER TABLE public.compliance_evaluations DROP CONSTRAINT %I', c.conname);
  END LOOP;
  ALTER TABLE public.compliance_evaluations ADD CONSTRAINT compliance_evaluations_surface_check
    CHECK (surface IN ('call', 'sms', 'email', 'quote', 'contract', 'fm_submission'));
END $$;

-- 2. Validator: fm_* kinds validated here, everything else by the original function ---------
-- lint:allow-destructive wraps compliance_version_errors by renaming the live implementation to compliance_version_errors_core (guarded, idempotent, signature unchanged for callers)
DO $$
BEGIN
  IF to_regprocedure('public.compliance_version_errors_core(text,text,text,text[],text,text,jsonb,jsonb,date,date)') IS NULL THEN
    ALTER FUNCTION public.compliance_version_errors(text, text, text, text[], text, text, jsonb, jsonb, date, date)
