END $$;

-- Mirror of validateFmParams / validateVersionDraft (fm kinds) in compliance-rules/fmSubmission.ts.
CREATE OR REPLACE FUNCTION public.compliance_version_errors(
  p_jurisdiction text, p_kind text, p_severity text, p_applies text[], p_title text, p_explanation text,
  p_params jsonb, p_refs jsonb, p_from date, p_to date
) RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = public AS $$
DECLARE
  e text[] := '{}';
  s text;
  d jsonb;
  v_num numeric;
  v_max int;
  v_cats text[] := ARRAY['labor', 'technicians', 'materials', 'trip', 'freight', 'sales_tax', 'new_business_fee', 'management_fee', 'other'];
  v_docs text[] := ARRAY['invoice', 'proposal', 'parts_order'];
BEGIN
  IF p_kind IS NULL OR p_kind NOT LIKE 'fm\_%' THEN
    RETURN public.compliance_version_errors_core(p_jurisdiction, p_kind, p_severity, p_applies, p_title, p_explanation, p_params, p_refs, p_from, p_to);
  END IF;
  IF p_kind NOT IN ('fm_nte_cap', 'fm_proposal_before_parts', 'fm_invoice_deadline', 'fm_ineligibility_window',
                    'fm_prohibited_line_item', 'fm_single_invoice', 'fm_required_attachment') THEN
    RETURN ARRAY['unknown rule kind'];
  END IF;
  IF p_jurisdiction IS DISTINCT FROM 'US' THEN e := array_append(e, 'portal rules use jurisdiction US'); END IF;
  IF COALESCE(p_severity, '') NOT IN ('block', 'require', 'warn', 'info') THEN e := array_append(e, 'severity must be block | require | warn | info'); END IF;
  IF char_length(btrim(COALESCE(p_title, ''))) < 3 THEN e := array_append(e, 'title is required'); END IF;
  IF char_length(btrim(COALESCE(p_explanation, ''))) < 20 THEN e := array_append(e, 'owner explanation must be at least 20 characters'); END IF;
  IF p_applies IS NULL OR cardinality(p_applies) = 0 THEN
    e := array_append(e, 'choose at least one surface');
  ELSE
    FOREACH s IN ARRAY p_applies LOOP
      IF s <> 'fm_submission' THEN e := array_append(e, format('%s cannot apply to %s', p_kind, s)); END IF;
    END LOOP;
  END IF;
  IF COALESCE(jsonb_typeof(p_refs), '') <> 'array' OR COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(p_refs) = 'array' THEN p_refs END), 0) = 0 THEN
    e := array_append(e, 'at least one source reference with a citation is required');
  ELSE
    FOR d IN SELECT * FROM jsonb_array_elements(p_refs) LOOP
      IF jsonb_typeof(d) <> 'object' OR btrim(COALESCE(d ->> 'citation', '')) = '' THEN
        e := array_append(e, 'every source reference needs a citation'); EXIT;
      END IF;
    END LOOP;
  END IF;
  IF p_from IS NULL THEN e := array_append(e, 'effective-from is required'); END IF;
  IF p_to IS NOT NULL AND p_from IS NOT NULL AND p_to < p_from THEN e := array_append(e, 'effective-to must be on or after effective-from'); END IF;
  IF COALESCE(jsonb_typeof(p_params), '') <> 'object' THEN RETURN array_append(e, 'params must be an object'); END IF;

  IF p_params ? 'documentTypes' THEN
    IF jsonb_typeof(p_params -> 'documentTypes') <> 'array'
       OR jsonb_array_length(p_params -> 'documentTypes') = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_params -> 'documentTypes') x
                  WHERE jsonb_typeof(x) <> 'string' OR NOT ((x #>> '{}') = ANY (v_docs))) THEN
      e := array_append(e, 'documentTypes must be a non-empty list of invoice | proposal | parts_order');
    END IF;
  END IF;

  IF p_kind IN ('fm_invoice_deadline', 'fm_ineligibility_window') THEN
    IF COALESCE(jsonb_typeof(p_params -> 'days'), '') <> 'number' THEN
      e := array_append(e, 'days must be an integer');
    ELSE
      v_num := (p_params ->> 'days')::numeric;
      v_max := CASE WHEN p_kind = 'fm_invoice_deadline' THEN 365 ELSE 1095 END;
      IF v_num <> trunc(v_num) OR v_num < 1 OR v_num > v_max THEN
        e := array_append(e, format('days must be an integer 1-%s', v_max));
      END IF;
    END IF;
    IF p_params ? 'warnDays' THEN
      IF COALESCE(jsonb_typeof(p_params -> 'warnDays'), '') <> 'number' THEN
        e := array_append(e, 'warnDays must be an integer 0-60');
      ELSE
        v_num := (p_params ->> 'warnDays')::numeric;
        IF v_num <> trunc(v_num) OR v_num < 0 OR v_num > 60 THEN e := array_append(e, 'warnDays must be an integer 0-60'); END IF;
      END IF;
    END IF;
    IF p_params ? 'anchor' AND COALESCE(p_params ->> 'anchor', '') NOT IN ('work_confirmed', 'work_received') THEN e := array_append(e, 'anchor must be work_confirmed or work_received'); END IF;

  ELSIF p_kind = 'fm_prohibited_line_item' THEN
    IF COALESCE(jsonb_typeof(p_params -> 'categories'), '') <> 'array'
       OR jsonb_array_length(CASE WHEN jsonb_typeof(p_params -> 'categories') = 'array' THEN p_params -> 'categories' ELSE '[]'::jsonb END) = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_params -> 'categories') = 'array' THEN p_params -> 'categories' ELSE '[]'::jsonb END) x
                  WHERE jsonb_typeof(x) <> 'string' OR NOT ((x #>> '{}') = ANY (v_cats))) THEN
      e := array_append(e, 'categories must be a non-empty list of known line categories');
    END IF;
    IF p_params ? 'appliesWhenBilling' AND COALESCE(p_params ->> 'appliesWhenBilling', '') NOT IN ('portal', 'customer') THEN
      e := array_append(e, 'appliesWhenBilling must be portal or customer');
    END IF;

  ELSIF p_kind = 'fm_required_attachment' THEN
    IF COALESCE(p_params ->> 'attachment', '') !~ '^[a-z0-9_-]{2,40}$' THEN e := array_append(e, 'attachment must match [a-z0-9_-]{2,40}'); END IF;
    IF btrim(COALESCE(p_params ->> 'label', '')) = '' THEN e := array_append(e, 'label is required'); END IF;
    IF p_params ? 'condition' AND COALESCE(p_params ->> 'condition', '') NOT IN ('always', 'has_subcontractor') THEN
      e := array_append(e, 'condition must be always or has_subcontractor');
    END IF;
  END IF;
  RETURN e;
END $$;

-- 3. Seed: ServiceChannel Managed starter pack (in_review, never enforced until approved) ----
DO $seed_do$
DECLARE
  r jsonb;
  v_pack uuid;
  v_rule uuid;
  v_ver uuid;
BEGIN
  FOR r IN SELECT * FROM jsonb_array_elements($seed$[
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-nte-cap","kind":"fm_nte_cap","severity":"block","title":"ServiceChannel: invoice may not exceed the NTE","ownerExplanation":"ServiceChannel will not accept an invoice above the work order's current NTE (not-to-exceed). To bill more, you need an approved proposal that raises the NTE first. Vireek checks the invoice total against the NTE before you send it.","params":{"documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"Invoice may not exceed the NTE. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."},{"citation":"ServiceChannel University (provider): Invoices","type":"other","url":"https://servicechannel.atlassian.net/wiki/spaces/SCUCP/pages/614924513/Invoices","retrievedOn":"2026-11-04"}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-parts-need-proposal","kind":"fm_proposal_before_parts","severity":"warn","title":"ServiceChannel: get a proposal approved before ordering parts above the NTE","ownerExplanation":"When parts would push the job above the NTE, the customer expects an approved proposal before you commit to them. Vireek warns before you place a parts order that would exceed the NTE with no approved proposal.","params":{"documentTypes":["parts_order"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 10","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"The guide confirms check-in is blocked until a proposal is approved. UNVERIFIED: no explicit 'approval before ordering parts' sentence was located — confirm per customer. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-invoice-within-10-days","kind":"fm_invoice_deadline","severity":"warn","title":"ServiceChannel: invoice within 10 days of Completed/Confirmed","ownerExplanation":"ServiceChannel expects the invoice within 10 days of the work order reaching Completed/Confirmed. Vireek counts calendar days from that date and warns you before the window closes.","params":{"days":10,"warnDays":3,"anchor":"work_confirmed","documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, pp. 9, 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"10-day invoicing window counted from Completed/Confirmed; ServiceChannel's own learning page calls it a best practice. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."},{"citation":"ServiceChannel Learning Channel: Invoice promptly to get paid fast","type":"other","url":"https://servicechannel.com/learning-channel/get-paid-faster/","retrievedOn":"2026-11-04"}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-ineligible-after-90-days","kind":"fm_ineligibility_window","severity":"require","title":"ServiceChannel: not invoiced within 90 days becomes ineligible for billing","ownerExplanation":"A work order that is not invoiced within 90 days can become ineligible for billing, so the money is lost. Vireek counts the days and tells you in time to invoice or ask the customer for an exception.","params":{"days":90,"warnDays":14,"anchor":"work_received","documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"Ineligible after 90 days. UNVERIFIED: the guide and a ServiceChannel learning page word this differently ('becomes' vs 'may be') and do not state the start date precisely. The window is counted from the day the work order was RECEIVED (the earliest, safest start; same as Work-Order Guard) — reviewer to confirm whether Completed/Confirmed applies instead. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-no-sales-tax-billing-portal","kind":"fm_prohibited_line_item","severity":"block","title":"ServiceChannel: no sales tax line when you bill ServiceChannel","ownerExplanation":"Invoices billed to ServiceChannel are rejected if they contain a sales tax line. If you bill the customer directly, tax can be allowed, so Vireek only applies this rule when the billing party is ServiceChannel.","params":{"categories":["sales_tax"],"appliesWhenBilling":"portal","documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"Sales tax is rejected when billing ServiceChannel; allowed when billing the customer directly. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-no-new-business-fees","kind":"fm_prohibited_line_item","severity":"block","title":"ServiceChannel: no \"New Business Fee\" lines on proposals or invoices","ownerExplanation":"ServiceChannel does not allow New Business Fees as line items. Proposals that contain one are rejected automatically. Vireek flags the line so you can remove it before sending.","params":{"categories":["new_business_fee"],"documentTypes":["invoice","proposal"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, pp. 13, 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"New Business Fees may not appear as line items on proposals or invoices. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-one-invoice-per-work-order","kind":"fm_single_invoice","severity":"block","title":"ServiceChannel: one invoice per work order","ownerExplanation":"ServiceChannel accepts one invoice for each work order. A second invoice is refused, and a rejected invoice cannot be edited. Vireek stops you from creating a duplicate.","params":{"documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"One invoice per work order. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]},
{"packSlug":"servicechannel-managed-2026","packName":"ServiceChannel Managed (2026 Trade Partner Guide)","jurisdiction":"US","appliesTo":["fm_submission"],"ruleKey":"sc-subcontractor-invoice-attached","kind":"fm_required_attachment","severity":"require","title":"ServiceChannel: attach the subcontractor's invoice","ownerExplanation":"When a subcontractor did part of the work, ServiceChannel expects their invoice attached to yours. Vireek reminds you when a subcontractor is involved and nothing is attached.","params":{"attachment":"subcontractor_invoice","label":"Subcontractor invoice","condition":"has_subcontractor","documentTypes":["invoice"]},"sourceRefs":[{"citation":"ServiceChannel Trade Partner 2026 Guide for Success, p. 15","type":"other","url":"https://servicechannel.com/wp-content/uploads/2025/10/Trade-Partner-Guidelines-2026.pdf","retrievedOn":"2026-11-04","note":"Attach subcontractor invoices. Page number from the 2026 edition read on 2026-11-04 — reviewer must confirm against the current guide."}]}
]$seed$::jsonb) LOOP
    INSERT INTO public.compliance_packs (slug, name, jurisdiction)
    VALUES (r ->> 'packSlug', r ->> 'packName', r ->> 'jurisdiction')
    ON CONFLICT (slug) DO NOTHING;
    SELECT id INTO v_pack FROM public.compliance_packs WHERE slug = r ->> 'packSlug';

    INSERT INTO public.compliance_rules (pack_id, rule_key, kind)
    VALUES (v_pack, r ->> 'ruleKey', r ->> 'kind')
    ON CONFLICT (pack_id, rule_key) DO NOTHING;
    SELECT id INTO v_rule FROM public.compliance_rules WHERE pack_id = v_pack AND rule_key = r ->> 'ruleKey';

    IF NOT EXISTS (SELECT 1 FROM public.compliance_rule_versions WHERE rule_id = v_rule) THEN
      INSERT INTO public.compliance_rule_versions
        (rule_id, version, status, severity, applies_to, title, owner_explanation, params, source_refs,
         effective_from, authored_by_email, submitted_at)
      VALUES
        (v_rule, 1, 'in_review', r ->> 'severity',
         ARRAY(SELECT jsonb_array_elements_text(r -> 'appliesTo')),
         r ->> 'title', r ->> 'ownerExplanation', r -> 'params', r -> 'sourceRefs',
         DATE '2026-11-04', 'system@vireek', now())
      RETURNING id INTO v_ver;
      INSERT INTO public.compliance_review_events (version_id, action, from_status, to_status, notes, actor_email)
      VALUES (v_ver, 'seeded', NULL, 'in_review', 'Starter portal rule drafted from the ServiceChannel 2026 Trade Partner Guide — a reviewer must confirm the citation before approval.', 'system@vireek');
    END IF;
  END LOOP;
END $seed_do$;

